import { injectable, inject } from "tsyringe";
import { DriveService } from "@/modules/media/infrastructure/drive.service.js";
import type { BulkParsedMedia } from "./bulk-product.dto.js";

// ── Types ────────────────────────────────────────────────────────────────────

export interface DriveFileRef {
  id: string;
  name: string;
  mimeType: string;
  /** Proxy URL generated by the backend — never a direct OAuth-scoped URL. */
  previewUrl: string;
  /** Google Drive thumbnail link for fast low-bandwidth previews (no auth required). */
  thumbnailLink?: string;
}

export interface MatchedEntry {
  reference: string; // filename stub or identifier from the draft
  file: DriveFileRef;
  mediaIndex: number; // index in the parsed media array
  productGroupId?: string;
  variantSku?: string;
}

export interface MissingEntry {
  reference: string;
  mediaIndex: number;
  productGroupId?: string;
  variantSku?: string;
}

export interface AmbiguousEntry {
  reference: string;
  candidates: DriveFileRef[];
  mediaIndex: number;
  productGroupId?: string;
  variantSku?: string;
}

export interface DuplicateEntry {
  reference: string;
  occurrences: number[]; // mediaIndex values that share the same filename/identifier
  file?: DriveFileRef;
}

export interface ImageMatchResult {
  matched: MatchedEntry[];
  missing: MissingEntry[];
  ambiguous: AmbiguousEntry[];
  duplicates: DuplicateEntry[];
  /** Total Drive files inspected in the folder. */
  folderFileCount: number;
}

// ── Service ──────────────────────────────────────────────────────────────────

/**
 * Matches the image references inside a parsed draft's media list against
 * files available in a Google Drive folder.
 *
 * Matching strategy (in priority order):
 *   ✓ Exact match (e.g. "NAVO2845.JPG" matches "NAVO2845.JPG")  → `matched`
 *   ✓ Base match (e.g. "NAVO2845" matches "NAVO2845.JPG")        → `matched`
 *   ✓ Normalized match (strips zeros, e.g. "NAVO02845" ↔ "NAVO2845") → `matched`
 *   ✗ Multiple candidate files matching same identifier           → `ambiguous`
 *   ✗ No matching file found in Drive                             → `missing`
 *   ⚠ Same reference used in more than one media row             → `duplicates`
 *
 * Persists matching results in BulkImportDraft.imageMatches.
 * Tokens/credentials are never exposed to the client.
 */
@injectable()
export class DriveImageMatcherService {
  constructor(@inject(DriveService) private driveService: DriveService) {}

  async match(
    userId: string,
    folderId: string,
    mediaRefs: BulkParsedMedia[],
    /** Already-confirmed assignments from a previous run — preserved as-is. */
    confirmedAssignments: Record<string, string> = {}
  ): Promise<ImageMatchResult> {
    // ── 1. List all files in the Drive folder (recursive, shared drives) ────
    let driveFiles: Array<{ id: string; name: string; mimeType: string; thumbnailLink?: string }>;
    try {
      driveFiles = await this.driveService.listFolderFiles(userId, folderId);
    } catch (err: any) {
      throw new Error(`Drive folder listing failed: ${err.message}`);
    }

    // ── 2. Build lookups: exact name, base name, normalized (zero-stripped) ─
    const byExactName = new Map<string, DriveFileRef[]>();
    const byBaseName = new Map<string, DriveFileRef[]>();
    const byNormalized = new Map<string, DriveFileRef[]>();
    const fileById = new Map<string, DriveFileRef>();

    for (const f of driveFiles) {
      if (!f.id || !f.name) continue;

      const ref: DriveFileRef = {
        id: f.id,
        name: f.name,
        mimeType: f.mimeType ?? "application/octet-stream",
        previewUrl: `/api/products/bulk/drive-proxy/${f.id}`,
        thumbnailLink: f.thumbnailLink || undefined,
      };

      fileById.set(f.id, ref);

      // Exact name normalized (lowercase, trimmed)
      const exactKey = normalise(f.name);
      addToMap(byExactName, exactKey, ref);

      // Base name (without extension)
      const base = stripExtension(f.name);
      const baseKey = normalise(base);
      addToMap(byBaseName, baseKey, ref);

      // Normalized key: strip internal zero-padding from numeric segments
      // e.g. "NAVO02845" → "navo2845", "NAV02845" → "nav2845"
      const normKey = normaliseZeros(base);
      addToMap(byNormalized, normKey, ref);
    }

    // ── 3. Extract identifier references for each media row ─────────────────
    const refs = mediaRefs.map((m, idx) => {
      const extracted = extractRef(m.url || m.altText || m.title || "");
      return { key: extracted, idx, media: m };
    });

    // ── 4. Detect duplicate references across draft media rows ───────────────
    const refOccurrences = new Map<string, number[]>();
    for (const r of refs) {
      if (!r.key) continue;
      const normalizedKey = normalise(r.key);
      const arr = refOccurrences.get(normalizedKey) ?? [];
      arr.push(r.idx);
      refOccurrences.set(normalizedKey, arr);
    }

    const seenDuplicates = new Set<string>();
    const duplicates: DuplicateEntry[] = [];
    for (const [normKey, indices] of refOccurrences.entries()) {
      if (indices.length > 1) {
        seenDuplicates.add(normKey);
        const candidates =
          byExactName.get(normKey) ||
          byBaseName.get(normKey) ||
          byNormalized.get(normaliseZeros(normKey));
        duplicates.push({
          reference: refs[indices[0]].key,
          occurrences: indices,
          file: candidates && candidates.length > 0 ? candidates[0] : undefined,
        });
      }
    }

    // ── 5. Run matching per media reference ──────────────────────────────────
    const matched: MatchedEntry[] = [];
    const missing: MissingEntry[] = [];
    const ambiguous: AmbiguousEntry[] = [];

    for (const r of refs) {
      const { key, idx, media } = r;

      // Check if user has an explicit confirmed assignment for this index or key
      const confirmedFileId =
        confirmedAssignments[String(idx)] ||
        confirmedAssignments[key] ||
        confirmedAssignments[normalise(key)];

      if (confirmedFileId) {
        const confirmedFile = fileById.get(confirmedFileId);
        if (confirmedFile) {
          matched.push({
            reference: key,
            file: confirmedFile,
            mediaIndex: idx,
            productGroupId: media.productGroupId,
            variantSku: media.variantSku,
          });
          continue;
        }
      }

      if (!key) {
        missing.push({
          reference: "",
          mediaIndex: idx,
          productGroupId: media.productGroupId,
          variantSku: media.variantSku,
        });
        continue;
      }

      const exactKey = normalise(key);
      const baseKey = normalise(stripExtension(key));
      const normZeroKey = normaliseZeros(stripExtension(key));

      // Priority 1: exact name match (e.g. "NAVO2845.JPG" → "NAVO2845.JPG")
      let candidates = byExactName.get(exactKey);

      // Priority 2: base name match (e.g. "NAVO2845" → "NAVO2845.JPG")
      if (!candidates || candidates.length === 0) {
        candidates = byBaseName.get(baseKey);
      }

      // Priority 3: normalized zero-stripped match (e.g. "NAVO02845" → "NAVO2845.JPG")
      if (!candidates || candidates.length === 0) {
        candidates = byNormalized.get(normZeroKey);
      }

      if (!candidates || candidates.length === 0) {
        missing.push({
          reference: key,
          mediaIndex: idx,
          productGroupId: media.productGroupId,
          variantSku: media.variantSku,
        });
      } else if (candidates.length === 1) {
        matched.push({
          reference: key,
          file: candidates[0],
          mediaIndex: idx,
          productGroupId: media.productGroupId,
          variantSku: media.variantSku,
        });
      } else {
        ambiguous.push({
          reference: key,
          candidates,
          mediaIndex: idx,
          productGroupId: media.productGroupId,
          variantSku: media.variantSku,
        });
      }
    }

    return {
      matched,
      missing,
      ambiguous,
      duplicates,
      folderFileCount: driveFiles.length,
    };
  }
}

// ── Helpers ──────────────────────────────────────────────────────────────────

function addToMap<T>(map: Map<string, T[]>, key: string, value: T): void {
  const bucket = map.get(key) ?? [];
  bucket.push(value);
  map.set(key, bucket);
}

/** Normalises a filename or identifier for comparison: lowercase, trim. */
function normalise(name: string): string {
  return name.trim().toLowerCase();
}

/** Strips extension if present: "photo.jpg" → "photo" */
function stripExtension(name: string): string {
  const lastDot = name.lastIndexOf(".");
  if (lastDot > 0) {
    return name.substring(0, lastDot);
  }
  return name;
}

/**
 * Normalises a base filename by collapsing internal zero-padding in numeric segments.
 * "NAVO02845" → "navo2845", "NAV02845" → "nav2845", "NAVO2845" → "navo2845"
 * This allows cross-matching when the JSON uses "NAVO2845" but the file is "NAVO02845".
 */
function normaliseZeros(name: string): string {
  return name
    .trim()
    .toLowerCase()
    .replace(/0+(\d)/g, "$1"); // collapse leading zeros in each numeric run
}

/**
 * Extracts a comparable reference key from a media URL, path, or identifier string.
 */
export function extractRef(url: string): string {
  if (!url) return "";
  try {
    const parsed = new URL(url);
    const pathname = parsed.pathname;
    return pathname.substring(pathname.lastIndexOf("/") + 1);
  } catch {
    const parts = url.split(/[/\\]/);
    return parts[parts.length - 1] ?? url;
  }
}
